begin;
set local search_path=public,extensions;
create extension if not exists pgtap with schema extensions;
select no_plan();
create temporary table ux_ids(key text primary key,id uuid not null);
grant all on ux_ids to authenticated,service_role;
insert into ux_ids select key,gen_random_uuid() from unnest(array['a','b','claim','stale']) key;
create function pg_temp.uid(key text) returns uuid language sql stable as $$select id from pg_temp.ux_ids where ux_ids.key=$1$$;
insert into auth.users(id,email) select id,'ux-'||key||'@example.invalid' from ux_ids where key in ('a','b');
insert into public.users(id,email,role) select id,'ux-'||key||'@example.invalid','PLAYER' from ux_ids where key in ('a','b');
insert into public.players(id,user_id,first_name,category_name,preferred_side,preferred_hand)
  select id,id,key,'9na','DRIVE','RIGHT' from ux_ids where key in ('a','b');
select ok(not has_function_privilege('anon','public.send_solo_player_request_with_preferences(uuid,uuid,text,text,text,text,text)','EXECUTE'),'anon cannot send proposals');
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.uid('b')::text,true);
insert into ux_ids values('post',(select id from public.save_solo_player_post(pg_temp.uid('b'),'9na','DRIVE','RIGHT','+5491123456789',false,'solo-players-contact-v1',null,'1_DAY')));
select set_config('request.jwt.claim.sub',pg_temp.uid('a')::text,true);
select throws_ok($$select public.send_solo_player_request_with_preferences(pg_temp.uid('post'),pg_temp.uid('b'),'+5491199999999','solo-players-contact-v1',null,'REVES','LEFT')$$,'42501',null,'cannot submit another player');
select throws_ok($$select public.send_solo_player_request_with_preferences(pg_temp.uid('post'),pg_temp.uid('a'),'+5491199999999','solo-players-contact-v1',null,'INVALID','LEFT')$$,'22023',null,'invalid game data rejected');
insert into ux_ids values('request',(select id from public.send_solo_player_request_with_preferences(pg_temp.uid('post'),pg_temp.uid('a'),'+5491199999999','solo-players-contact-v1',null,'REVES','LEFT')));
select is((select sender_preferred_side from public.solo_player_request_inbox where id=pg_temp.uid('request')),'REVES','side saved on the request');
select is((select sender_preferred_hand from public.solo_player_request_inbox where id=pg_temp.uid('request')),'LEFT','hand saved on the request');
select is((select preferred_side::text from public.players where id=pg_temp.uid('a')),'DRIVE','profile side preserved');
select is((select preferred_hand from public.players where id=pg_temp.uid('a')),'RIGHT','profile hand preserved');
reset role;
update public.solo_player_notifications set email_next_attempt_at=now()+interval '1 day' where request_id is distinct from pg_temp.uid('request');
set local role service_role;
insert into ux_ids values('notification',(select id from public.claim_solo_player_emails(pg_temp.uid('claim'),1)));
select ok(not public.finish_solo_player_email(pg_temp.uid('notification'),pg_temp.uid('stale'),false,'EMAIL_DISABLED'),'stale lease cannot skip an email');
select ok(public.finish_solo_player_email(pg_temp.uid('notification'),pg_temp.uid('claim'),false,'EMAIL_DISABLED'),'current lease can suppress opted-out email');
select is((select email_status from public.solo_player_notifications where id=pg_temp.uid('notification')),'SKIPPED','suppressed email is terminal');
select ok((select email_sent_at is null from public.solo_player_notifications where id=pg_temp.uid('notification')),'suppression never claims a delivery');
select ok(exists(select 1 from public.solo_player_notifications where id=pg_temp.uid('notification') and read_at is null),'in-app notification retained unread');
select is((select count(*) from public.claim_solo_player_emails(pg_temp.uid('claim'),20)),1::bigint,'only the other recipient remains in the email queue');
select is((select count(*) from public.claim_solo_player_emails(pg_temp.uid('claim'),20)),0::bigint,'skipped emails never retry');
reset role;
select * from finish();
rollback;
